import{_ as e,c as p,o as r,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"55、【丰】 离下震上","description":"周易尚氏学 - 55、【丰】 离下震上","frontmatter":{"title":"55、【丰】 离下震上","description":"周易尚氏学 - 55、【丰】 离下震上"},"headers":[],"relativePath":"zh/classics/shangshi/060.md","filePath":"zh/classics/shangshi/060.md"}'),s={name:"zh/classics/shangshi/060.md"};function h(t,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_55、【丰】-离下震上" tabindex="-1">55、【丰】 离下震上 <a class="header-anchor" href="#_55、【丰】-离下震上" aria-label="Permalink to “55、【丰】 离下震上”">​</a></h1><p>雷电皆至东。故丰。说文。丰豆之丰满者也。四阳遇重阴。故亨。震为王。假至也。王假之。言四宜上升至五也。震为乐。故曰勿忧。离为日。中谓五。宜日中者。谓四升五。当位如日中也。</p><p>彖曰。丰。大也。明以动故丰。王假之。尚大也。勿忧宜日中。宜照天下也。日中则昃。月盈则食。天地盈虚。与时消息。而况于人乎。况于鬼神乎。</p><p>尚上也。大谓阳。尚大谓四宜上升五。四升五则日中。光照天下。兑月离日。日中则昃。月盈则食。言丰之不足恃也。</p><p>象曰。雷电皆至。丰。君子以折狱致刑。</p><p>先天离东。后天震东。故曰皆至。离明故可折狱。震威故宜致刑。</p><p>初九。遇其配主。虽旬无咎。往有尚。</p><p>阴阳相配。配主谓二。二五为卦主。故五曰夷主。配郑作妃。义同也。离为日。日之数十。十日为旬。初居日之末。故曰旬。至旬则癸日也。后汉邓禹传。明日癸亥。匡等以六甲穷日。不出。是至旬当有咎。自古相传如是也。虽旬无咎者。以初遇阴也。二阴。故往有尚。</p><h3 id="象曰。虽旬无咎。过旬灾也。" tabindex="-1">象曰。虽旬无咎。过旬灾也。 <a class="header-anchor" href="#象曰。虽旬无咎。过旬灾也。" aria-label="Permalink to “象曰。虽旬无咎。过旬灾也。”">​</a></h3><p>旬者盈数。过旬灾。仍月盈则食之意也。</p><p>六二。丰其部。日中见斗。往得疑疾。有孚发若。吉。</p><p>二至五五大坎。坎为隐伏。故中四爻象皆阎昧。部（上草）。虞翻云。日蔽云中称部（上草）。虞未申其义。然坎云在离日之上。正日蔽云中也。离为星。故日斗。又震亦为斗。斗七星也。言离日有障蔽。日隐而星见也。二巽体。巽为疑为疾。巽初六象曰。进退志疑是也。五不应。故往得疑疾。然二承重阳。手于三四。发若者。言其顺利也。阴孚阳故吉。离星巽疑象详焦氏易诂。</p><h3 id="象曰。有孕发若。信以发志也。" tabindex="-1">象曰。有孕发若。信以发志也。 <a class="header-anchor" href="#象曰。有孕发若。信以发志也。" aria-label="Permalink to “象曰。有孕发若。信以发志也。”">​</a></h3><p>有孚故信。巽为志。信以发志者。言阴孚于阳。得行其志也。</p><p>九三。丰其沛。日中见沫。折其右肱。无咎。</p><p>沛大雨貌。孟子沛然下雨。易林泰之丰云。龙蛇所聚。大水来处。滂滂沛沛。使我无赖。九家云。大暗谓之沛。沫。子夏传星之小者。日中见沫者。言当日中而昏暗见小星也。三兑体。兑为雨。故曰沛。兑为晦。故曰见沫。艮为肱三应在上。上艮覆。故折其右肱。兑为右为折也。然三当位有应。故无咎。</p><h3 id="象曰。丰其沛。不可大事也。折其右肱。终不可用也。" tabindex="-1">象曰。丰其沛。不可大事也。折其右肱。终不可用也。 <a class="header-anchor" href="#象曰。丰其沛。不可大事也。折其右肱。终不可用也。" aria-label="Permalink to “象曰。丰其沛。不可大事也。折其右肱。终不可用也。”">​</a></h3><p>三遇敌。不利往。所应为阴。阴小故不可大事。三虽有应而折肱。故终不可用。虞氏以二至五大过死解。似非。</p><p>九四。丰其蔀，日中见斗。遇其夷主，吉。</p><p>易林升之临云。据斗运枢。以震为斗。兹震在日上。以为障蔽。故仍曰丰其部（上草）。日中见斗。主谓五。五柔爻。故曰夷主。诗周颂有夷之行。毛传。夷易也。阳遇阴则通。故曰易曰。曰吉。</p><h3 id="象曰。丰其蔀-位未当也。日中见斗-幽不明也。遇其夷主-吉行也。" tabindex="-1">象曰。丰其蔀，位未当也。日中见斗，幽不明也。遇其夷主，吉行也。 <a class="header-anchor" href="#象曰。丰其蔀-位未当也。日中见斗-幽不明也。遇其夷主-吉行也。" aria-label="Permalink to “象曰。丰其蔀，位未当也。日中见斗，幽不明也。遇其夷主，吉行也。”">​</a></h3><p>易林升之临云。据斗运枢，以震为斗。兹震在日上。以为障蔽。故仍日半其部（上草）日中见斗。主谓五。五柔爻。故曰夷主。诗周颂有夷之行。创传。夷易也。阳遇阴则通。故曰易。日吉。象曰。半其部（上草）。位不当也。日中见斗。幽不明也。遇其夷主。吉行也。兑为昧。故幽不明。阳遇阴故志行。郭京举正行上脱志字。宜从。</p><p>六五。来章。有庆誉。吉。</p><p>呼九四来五。当位居中。彖所谓日中也。故曰章。五得位。故有庆誉吉。或谓四往五不能曰来。岂知六五呼四。当然曰来。况睽上九云。往遇雨则吉。是上来内。易有时亦言往也。需上曰有不速之客三人来。是三往上亦曰来也。蹇五大蹇朋来。是阳往五亦曰来也。上曰来章。又何疑乎。</p><h3 id="象曰。六五之吉。有庆也。" tabindex="-1">象曰。六五之吉。有庆也。 <a class="header-anchor" href="#象曰。六五之吉。有庆也。" aria-label="Permalink to “象曰。六五之吉。有庆也。”">​</a></h3><p>庆谓阳升五得位。</p><p>上六。丰其屋，蔀其家，窥其户，阒其无人，三岁不觌，凶。</p><p>屋家户。后儒不知其象。穿凿百出。愈说愈晦。此覆象失传之故也。按虞注云。从外窥三。又九家说重门系柝云。豫不艮。从外示之。上震复为艮。丰上六从外示内。亦艮也。艮为屋为家为户。中爻大坎。故障蔽其家。艮为观。下视。故曰窥其户。震为人。上应在三。三巽伏。故阒寂无人。阒虞云空也。郑云无人儿。震为岁。数三。故曰三岁不觌而凶也。阒孟喜作室。窒古与空通用。列子黄帝篇。玉人潜行不空。庄子达生篇引作室。然则孟虞之诂同也。</p><h3 id="象曰。丰其屋。天际祥也。窥其户阒其无人。自藏也。" tabindex="-1">象曰。丰其屋。天际祥也。窥其户阒其无人。自藏也。 <a class="header-anchor" href="#象曰。丰其屋。天际祥也。窥其户阒其无人。自藏也。" aria-label="Permalink to “象曰。丰其屋。天际祥也。窥其户阒其无人。自藏也。”">​</a></h3><p>五天位。上在五外。故曰天际。说文祥福也善也。徐肱曰。凡吉凶之先见其兆者。皆曰祥。故孟喜曰。天际祥。天降下恶祥也。自藏谓三。三宜应上。而巽为伏。故曰自藏。释无人之故也。祥从郑本。正义作翔。翔样音同通用。此卦旧解。因易理失传。不知二五为卦主。于是遇其配主。遇其夷主。皆以震为主。权栎不合。因卦象失传。于是爻变卦变。杂然并用。以求其象。学者只涵泳白文。或尚能明其一二。若即旧解求之。则愈茫昧疑惑。真可慨也。</p>',30)])])}const f=e(s,[["render",h]]);export{_ as __pageData,f as default};
